window.products.push({"id":432970,"name":"Swissmar Oval Slate Board","category":"homeandappliances","retail price":23.36,"sale price":null,"image":"https://m.media-amazon.com/images/I/51stMxnpp4L._AC_SL1000_.jpg","description":"Slate is a naturally occurring rock formed millions of years ago from clay or volcanic rash. Mined in Northern China, each piece is unique and hand crafted with natural unfinished edges. Finished with felt pads on the bottom, this board can be wiped clean with a damp cloth. Because of the nature of slate, some cheeses may leave dark spots on the board if left for a prolonged period of time. If this happens, simply wipe the entire board with olive oil.","images":["https://m.media-amazon.com/images/I/51stMxnpp4L._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Swissmar","source_asin":"B01JBTLA0Y","category_path":"Home & Kitchen"},"sku":"BM-432970","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01JBTLA0Y","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01JBTLA0Y","price_pending":true,"merchant_ready":false});
